(function(){'use strict';var gallery=document.querySelector('[data-pd-gallery]');if(gallery){var main=gallery.querySelector('[data-pd-main]');var stage=gallery.querySelector('[data-pd-stage]');var strip=gallery.querySelector('[data-pd-strip]');var countEl=gallery.querySelector('[data-pd-count]');var thumbs=Array.prototype.slice.call(gallery.querySelectorAll('[data-pd-thumb]'));var prevBtn=gallery.querySelector('[data-pd-prev]');var nextBtn=gallery.querySelector('[data-pd-next]');var isMulti=gallery.classList.contains('is-multi');if(main&&thumbs.length){var total=thumbs.length;var idx=0;var drag={on:false,x0:0,y0:0,dx:0,pid:null};function at(n){return thumbs[(n+total)%total];}
function setA11y(){thumbs.forEach(function(t,n){var on=(n===idx);t.setAttribute('aria-selected',on?'true':'false');t.tabIndex=on?0:-1;});if(strip)strip.setAttribute('aria-activedescendant','');}
function centerThumb(el){if(!strip||!el)return;var rc=strip.getBoundingClientRect();var re=el.getBoundingClientRect();var delta=(re.left+re.width/2)-(rc.left+strip.clientWidth/2);strip.scrollBy({left:delta,behavior:'smooth'});}
function prefetch(n){var url=at(n).getAttribute('data-full');if(url){var im=new Image();im.src=url;}}
function show(n){if(!total)return;idx=(n+total)%total;var t=thumbs[idx];var url=t.getAttribute('data-full');if(url){main.src=url;main.alt=t.getAttribute('data-alt')||main.alt;}
if(countEl&&isMulti)countEl.textContent=(idx+1)+' / '+total;setA11y();centerThumb(t);if(total>1){prefetch(idx+1);prefetch(idx-1);}}
thumbs.forEach(function(el,n){el.addEventListener('click',function(){show(n);});el.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();show(n);}});});if(prevBtn)prevBtn.addEventListener('click',function(e){e.stopPropagation();show(idx-1);});if(nextBtn)nextBtn.addEventListener('click',function(e){e.stopPropagation();show(idx+1);});if(stage){stage.addEventListener('keydown',function(e){if(e.key==='ArrowLeft'){e.preventDefault();show(idx+1);}
else if(e.key==='ArrowRight'){e.preventDefault();show(idx-1);}
else if(e.key==='Home'){e.preventDefault();show(0);}
else if(e.key==='End'){e.preventDefault();show(total-1);}});}
if(stage){stage.addEventListener('pointerdown',function(e){if(e.pointerType==='mouse'&&e.button!==0)return;if(e.target.closest&&e.target.closest('button'))return;drag.on=true;drag.x0=e.clientX;drag.y0=e.clientY;drag.dx=0;drag.pid=e.pointerId;try{stage.setPointerCapture(drag.pid);}catch(_){}
main.classList.add('is-dragging');});stage.addEventListener('pointermove',function(e){if(!drag.on||e.pointerId!==drag.pid)return;var dx=e.clientX-drag.x0;var dy=e.clientY-drag.y0;drag.dx=dx;if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>6){var pull=Math.max(-160,Math.min(160,dx));main.style.transform='translateX('+pull+'px)';main.style.opacity=String(Math.max(0.35,1-Math.abs(dx)/240));}});function endDrag(e){if(!drag.on||(e&&e.pointerId!==drag.pid))return;drag.on=false;var dx=drag.dx;main.style.transform='';main.style.opacity='';main.classList.remove('is-dragging');if(Math.abs(dx)>55){if(dx<0)show(idx+1);else show(idx-1);}}
stage.addEventListener('pointerup',endDrag);stage.addEventListener('pointercancel',endDrag);}
show(0);}}
var qtyWrap=document.querySelector('[data-pd-qty]');var addBtn=document.querySelector('[data-pd-add]');if(qtyWrap&&addBtn){var val=qtyWrap.querySelector('[data-pd-qty-val]');var max=parseInt(addBtn.getAttribute('data-max-qty')||'0',10)||0;var n=1;function sync(){if(val)val.textContent=n;addBtn.setAttribute('data-qty',n);}
var dec=qtyWrap.querySelector('[data-pd-qty-dec]');var inc=qtyWrap.querySelector('[data-pd-qty-inc]');if(dec)dec.addEventListener('click',function(){n=Math.max(1,n-1);sync();});if(inc)inc.addEventListener('click',function(){n=Math.min(max>0?max:99,n+1);sync();});sync();}})();;(function(){'use strict';var btn=document.querySelector('[data-pd-add]');if(!btn)return;function setAddedState(inCart){if(!btn||btn.disabled||btn.classList.contains('is-disabled'))return;var icon=btn.querySelector('i');var span=btn.querySelector('span');if(inCart){btn.classList.add('is-in-cart');btn.setAttribute('aria-pressed','true');if(icon)icon.className='fa-solid '+(btn.getAttribute('data-in-icon')||'fa-trash-can');if(span)span.textContent=btn.getAttribute('data-in-label')||'إزالة من السلة';btn.setAttribute('aria-label','إزالة '+(btn.dataset.title||'')+' من السلة');}else{btn.classList.remove('is-in-cart');btn.setAttribute('aria-pressed','false');if(icon)icon.className='fa-solid '+(btn.getAttribute('data-idle-icon')||'fa-cart-plus');if(span)span.textContent=btn.getAttribute('data-idle-label')||'إضافة للسلة';btn.setAttribute('aria-label','أضف '+(btn.dataset.title||'')+' إلى السلة');}}
window.__pdpBtnSync=function(){if(window.pdpCartIn)setAddedState(window.pdpCartIn(btn));};if(!window.onCartChanged){window.onCartChanged=function(){if(window.__pdpBtnSync)window.__pdpBtnSync();};}
window.__pdpBtnSync();})();